        public MemoryStream ExportExcelSMAStatement(StatementSMACriteria criteria, List<StatementSMAModel> data)
        {
            var result = new MemoryStream();
            var sheetName = ResourceExtension.GetResource(ResourceClass, "StatementName");

            var worksheet = _workbook.CreateSheet(sheetName);
            var titleRow = worksheet.CreateRow(0);
            var titleCell = titleRow.CreateCell(0);
            titleCell.SetCellValue(string.Format("{0} {1}-->{2}", sheetName, criteria.FromDate.ToString("MM/dd/yyyy"), criteria.ToDate.ToString("MM/dd/yyyy")));
            titleCell.CellStyle = _titleStyle;

            // Header
            var headerRow1 = worksheet.CreateRow(1);
            headerRow1.Sheet.SetColumnWidth(0, 5 * 256);
            headerRow1.Sheet.SetColumnWidth(1, 25 * 256);
            headerRow1.Sheet.SetColumnWidth(2, 60 * 256);
            headerRow1.Sheet.SetColumnWidth(3, 20 * 256);
            headerRow1.Sheet.SetColumnWidth(4, 20 * 256);
            var shiftCol = 1;

            headerRow1.CreateCell(1 - shiftCol).SetCellValue("#");
            headerRow1.GetCell(1 - shiftCol).CellStyle = _headerStyle;

            headerRow1.CreateCell(2 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "Date"));
            headerRow1.GetCell(2 - shiftCol).CellStyle = _headerStyle;

            headerRow1.CreateCell(3 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "Remark"));
            headerRow1.GetCell(3 - shiftCol).CellStyle = _headerStyle;

            headerRow1.CreateCell(4 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "Total"));
            headerRow1.GetCell(4 - shiftCol).CellStyle = _headerStyle;

            headerRow1.CreateCell(5 - shiftCol).SetCellValue(ResourceExtension.GetResource(ResourceClass, "AccummulatedTotal"));
            headerRow1.GetCell(5 - shiftCol).CellStyle = _headerStyle;

            var maxDataLenght = data.Count;

            for (int i = 0; i < maxDataLenght; i++)
            {
                var row = worksheet.CreateRow(i + _startRowNumber);
                row.HeightInPoints = 35;
                bool isEven = i % 2 == 1;
                var nocell = row.CreateCell(0);
                nocell.SetCellValue(data[i].No);
                nocell.CellStyle = isEven ? this._noCellStyleEven : this._noCellStyle;

                var winlostDatecell = row.CreateCell(1);
                HSSFRichTextString HSSwinlossDate = new HSSFRichTextString(data[i].WinlossDate.Replace("<br>", "\n"));
                winlostDatecell.SetCellValue(HSSwinlossDate);
                winlostDatecell.CellStyle = isEven ? this._winlostDateCellStyleEven : this._winlostDateCellStyle;

                var remarkDatecell = row.CreateCell(2);
                HSSFRichTextString HSSremark = new HSSFRichTextString(data[i].TransType + "\n -" + data[i].TransDesc);
                remarkDatecell.SetCellValue(HSSremark);
                remarkDatecell.CellStyle = isEven ? this._remarkCellStyleEven : this._remarkCellStyle;

                var totalcell = row.CreateCell(3);
                totalcell.SetCellValue(data[i].Total);
                totalcell.CellStyle = isEven ? this._totalCellStyleEven : this._totalCellStyle;

                var accummulatedTotalcell = row.CreateCell(4);
                if (data[i].IsOpeningBalance)
                {
                    accummulatedTotalcell.SetCellValue(data[i].AccumulatedTotalExcel);
                }
                else
                {
                    accummulatedTotalcell.SetCellValue(data[i].AccumulatedTotalNumber);
                }

                if (data[i].IsOpeningBalance)
                {
                    if (data[i].AccumulatedTotalExcel.Contains("NOT EQUAL") == true)
                    {
                        accummulatedTotalcell.CellStyle = isEven ? this._accummulatedBlackCellStyleEven : this._accummulatedBlackCellStyle;
                    }
                    else
                    {
                        accummulatedTotalcell.CellStyle = isEven ? this._accummulatedGreenCellStyleEven : this._accummulatedGreenCellStyle;
                    }
                }
                else
                {
                    accummulatedTotalcell.CellStyle = isEven ? this._accummulatedCellStyleEven : this._accummulatedCellStyle;
                }
            }

            _workbook.Write(result);
            return result;
        }

